INSERT INTO local_specialty (
    crop_name, local_name, region, source,
    content, source_url
) VALUES
('딸기', '논산딸기', '충청남도 논산시', '지역N문화', '충청남도 논산시는 우리나라 딸기 주산지로 전국 딸기 생산량의 약 20% 이상을 공급하고 있다. 논산에 딸기 재배 농가만 2,000여 농가에 재배면적은 1,000ha이다. 농업진흥원 딸기연구소에서는 2005년에 국산 품종 개발을 통해 해외로열티 지급에 종지부를 찍었다. 이후 설향이 전국적으로 대세품종으로 부각되어 전체 농가의 90%가 설향을 재배하기도 했다. 이후 설향의 단점을 보완해 킹스베리를 재배를 시작했는데, 2020년에 싱가포르 현지 셰프들이 한국산 딸기 품평회에서 킹스베리의 품질이 가장 좋다는 평을 받기도 하였다. 논산 딸기는 1967년 충청남도 논산시 채운면 용화리의 박상규 씨가 보령시 웅천면에서 ''다나'' 품종을 도입하면서부터 본격적으로 재배되었다. 그전에는 성동면 원봉리와 정지리 등에서 포도과수원의 간작으로 재배되었다. 이후 논산시에서 영농 기술이 발전하고, 재배면적이 증가하면서 2008년에서는 955ha를 재배하여 충청남도 딸기 재배면적의 45%, 전국 딸기 재배면적의 13%를 차지하여 전국 최대 딸기 주산지로 발돋움하였다. 2021년 기준으로 전국 딸기재배의 20%를 차지하고 있고, 한해 생산량은 2만 9,660톤이다. 현재 논산 딸기 재배 작목반은 180여개이며, 각 읍면단위의 농업협동조합에서 출하지원을 하고 있다. 충청남도 농업기술원 딸기연구소에서는 딸기를 우수한 품종으로 개량하고, 우량 종묘 생산 및 보급에 힘쓰고 있다. 연구소에서는 딸기의 유전자원을 수집하고 보존하거나, 딸기 품종육성과 생리 생태, 병해충방제 및 연작장해에 대한 시험 연구를 지속하고 있다. 연구소에서는 2001년에 품종 ''매향''을 보급하기 시작해, 꾸준히 품종 개량을 통해 만향(2003년), 설향(2005년), 금향(2005년), 숙향(2012년), 킹스베리(2016년), 두리향(2017년), 써니베리(2017년), 비타베리 등을 보급하였다. 연간 5~8만주의 우량모를 분양하고 있다. 이중 2005년 설향은 딸기 재배에 큰 획을 그었다. 국산품종 재배가 가능해지면서 전국 딸기재배 농가의 90%가 설향을 현재까지 재배할 정도로 인기가 높다. 해외로열티 문제가 해결됨으로써 딸기 재배의 자주화를 이룬 셈이다. 설향은 생산량이 많고, 병충해에도 강하고, 재배지 조건에도 크게 반응하지 않는 등의 재배 안정성을 갖추고 있어 큰 인기를 끌고 있다. 다만 과육이 무르고, 전국에서 재배되다 보니 출하 시기가 동일해 경쟁력 확보에 문제가 대두되었다. 달걀보다 크다고 하여 킹스베리라 이름붙인 딸기와 향과 당도를 높인 비타베리까지 꾸준히 재배가 이루어지고 있다. 2006년도에 논산시는 딸기산업특구로 지정되어 관리 중이다. 이에 일부 농가에서는 신품종을 재배하기 하고 있다. 그 대체 품종은 ''비타베리''로 출하시기를 달리 하기 위해 설향의 비율을 조금 줄이고, 신품종 재배에 열을 올리고 있다. 비타베리는 충남농촌진흥원 딸기연구소에서 개발한 신품종으로 딸기향이 진하고, 당도가 높은 것이 특징이다. 이를 주도하는 곳은 ''광석농협 딸기 공선회''이다. 이들은 비타베리를 동남아에 선보이며, 해외수출에 관심을 늘리고 있다. 딸기는 수경재배를 하므로 깨끗한 환경에서 재배가 가능하다. 출하가 연초에 이루어지므로 예비 귀농인이 가장 큰 관심을 보이고 있다. 설향과 신품종 재배를 통해 상호보완할 수 있는 토대마련이 가능하다. 농어촌공사 농지은행 공공임대 사업을 통해 재배농지도 임대받을 수 있으며, 임대료도 2,400평 기준으로 1년에 40만원으로 저렴하다. 논산시에서 지정하는 청년후계농에 선정된다면 창업자금까지 대출받을 수 있어 청년농업으로 부각되고 있다.', 'https://ncms.nculture.org/local-specialty/story/12249'),
('키위', '고성 참다래', '경상남도 고성군', '지역N문화', '경상남도 고성군 하일면 송천리는 참다래 마을로 유명하다. 이 지역에는 처음 약 20농가 정도가 참다래를 시작해서 꾸준히 농가도 늘고 참다래의 맛을 유지해 그 명성을 이어오고 있다. 이 참다래는 우리나라와 중국이 원산지로 알려져 있는데, 뉴질랜드에서 씨를 가져가서 새롭게 개발해서 키위라는 이름으로 불렀다. 키위라는 이름은 뉴질랜드의 나라 새 키위푸르트와 닮았기 때문이었다. 이를 다시 역 수입해서 우리 고유의 명칭 다래에 ''참''자를 넣어 참다래라 명하고, 재배해서 성공하였다. 이제는 우리나라에서 생산되는 참다래가 전국적으로 유통되고 있으며, 우리 고유의 다래 과일로 자리하고 있다. 고려가요 『청산별곡』에는 ''머루랑 다래를 먹고 청산에 살리라''는 구절이 있다. 고등학교 교과서에 나오는 구절이라 우리 국민들은 이 구절을 외우면서 복잡한 도시를 떠나 산촌에 가 사는 꿈을 꾸었다. 그런데 그 다래가 새롭게 개발되어 최고의 고품질 과일로 우리 식탁에 오를 줄은 아무도 몰랐다. 그것도 계절 과일이 저온 보관으로 일 년 내내 맛보는 과일로 먹을 수 있게 되었으니 정말 놀랄 일이다. 이처럼 다래는 우리나라와 중국 일대에서 야생으로 자라던 과일이다. 가을이면 산 어디를 가나 맛볼 수 있다. 그렇게 지천으로 자라는 다래 덩굴을 1904년 뉴질랜드 교사 이자벨 프레이져가 중국 양자강변에서 가져가 정원수로 심었다. 이 열매를 뉴질랜드 사람은 중국에서 가져왔다고 해서 차이니즈 구즈베리라 불렀다. 그런데 열매가 다 익으면 달고 맛있으므로 농민들이 보다 큰 열매와 대량 생산할 수 있는 개발을 시작했다. 그렇게 개발하다 보니 다래의 크기가 달라졌고, 맛도 다래와 다르게 변했다. 그리고 그 모양이 뉴질랜드의 국조(國鳥)인 ''키위프루트(Kiwifruit)''와 닮아서 키위라 부르게 되었다고 한다. 이 묘목을 1977년 우리나라 남해안에서 수입해 왔다. 의외로 다래의 품종이 우리 실정에 맞게 금방 변했고, 나무도 잘 자랐다. 마침 그때 농산물 수입 자유화가 추진되던 시기였으므로, 그 명칭을 키위에서 우리 고유의 명칭으로 바꾸고 야생 다래와 구별하기 위해 ''참다래''라고 하였다. 다래를 익히 알고 있는 우리나라 사람들은 호기심으로 구매해서 맛을 보았고, 그러다 보니 입에 맞아서 이제는 상시로 사 먹는 과일로 정착했다. 이런 다래를 경상남도 고성에 정착시킨 시기는 2002년이다. 참다래의 가치를 알아본 농민들은 영농조합을 만들고 참다래 생산에 들어갔다. 경상남도 고성군 하일면 송천리는 천혜의 참다래 생산 환경을 가지고 있다. 산과 바다가 어우러진 멋진 풍경을 가짐은 물론 다래가 생육할 수 있는 기후와 기온을 보유했다. 마을 옆에는 좌이산이 우뚝 솟았고 산 위에는 봉수대도 있으며, 산 반대 방향에는 넘실대는 남해의 멋진 바다가 해풍을 몰아 오고 있다. 그래서 송천리는 어떤 작물을 심어도 맛있는 곡물을 생산해 내고 있다. 참다래도 해풍을 맞아서 그 맛이 더 달고, 고성의 토질이 농산물이 잘 자라게 하는 물 빠짐이 좋고 영양분이 풍부한 땅이다. 고성군 농업기술센터와 참다래 마을에서는 더 좋은 참다래를 만들고자 꾸준히 품종 개발에 매달리고 있다. 현재 생산되는 참다래는 그린키위, 골드키위, 레드키위로 나뉜다. 그 품종마다 맛과 빛깔이 다르다. 그러면서 ''참다래유통사업단''을 만들고, 과수생산유통지원사업의 자금을 지원받아 새로운 품질로 개발하고, 농가를 확산해 가고 있다. 고성의 송천 참다래 농가는 점차 늘어가는 추세이다. 공동으로 판매와 유통을 하기 위해서 영농조합법인을 만들어서 운영하고 있다. 참다래를 고품질로 생산하기만 하면 시세에 흔들리지 않고 안정적인 수익을 이룰 수 있도록 했다. 그 가격은 방문객도 인터넷 판매도 백화점 납품도 모든 농가가 같다. 현장 체험을 하는 참가자 수도 꾸준히 늘어서 2024년의 경우 1만 명을 돌파했다고 한다.', 'https://ncms.nculture.org/local-specialty/story/'),
('파프리카', '철원 파프리카', '강원도 철원군', '지역N문화', '피망의 매운맛은 빼고 단맛은 더한 후 과육이 많게 개량한 파프리카는 강원도 철원군의 특산물 중의 하나로 초록빛만을 띠는 피망과 달리 빨간색, 주황색, 노란색, 초록색으로 색깔이 다양하고, 색깔에 따라 효능 또한 다르다. 강원도 철원의 특산물인 파프리카의 재배 초기에는 재배 면적이 넓지 않았다. 2011년에 약 35ha였던 파프리카 재배 면적은 2016년에는 약 159ha로 급속도로 확대됐다. 이렇게 재배한 파프리카는 생식으로 먹거나 소스나 조미료로 만들어 요리에 활용된다. 파프리카의 원산지는 중앙아메리카이다. 파프리카라는 말의 어원은 희랍어인데, 유럽에서는 모든 고추를 파프리카라고 통칭한다. 이와 달리 우리나라에서는 매운맛이 없는 벨타입(Bell Type)의 고추인 단고추를 파프리카라고 일컫는다. 영어로는 bell pepper 또는 sweet pepper라고 한다. 우리나라에서 재배되고 있는 파프리카는 네덜란드에서 수입한 품종이다. 우리나라에서 재배되는 파프리카는 지역에 따라 재배되는 시기가 다르다. 전라북도 김제시, 전라남도 화순군과 영광군, 경상남도 진주시 등의 남부 평야 지역에서는 주로 겨울에 재배되고, 전라북도 남원시, 경상남도 합천군, 강원도 지역에서는 여름에 주로 재배가 이루어진다. 강원도 철원에서 파프리카가 주로 재배되는 곳은 서면·근남면·김화읍이다. 강원도의 특산물인 파프리카의 재배 초기에는 재배 면적이 넓지 않았다. 1997년에 철원군에서 파프리카를 재배했던 면적은 4ha뿐이었다. 수출용으로만 파프리카를 재배했기 때문이다. 그러다가 일본에서 파프리카의 소비량이 늘어나면서 1999년에도 파프리카의 재배 면적이 52ha까지 확대되고, 국내 소비가 늘어난 2000년대 이후에는 재배 면적이 크게 늘게 되었다. 2011년에 약 35ha였던 파프리카 재배 면적은 2016년에는 약 159ha로 급속도로 확대됐다. 2015년 하반기를 기준으로 가락시장에서 유통된 평균 38% 정도의 파프리카가 강원도 철원군에서 출하된 것이었다. 이뿐만 아니라 철원군에서 수출한 파프리카는 830톤에 달했으며 그 금액은 200만 달러였다. 파프리카는 19℃에서 22℃ 사이로 기온이 유지되어야 재배가 가능하다. 강원도 철원군의 평균 기온은 12.75℃이기 때문에 파프리카가 재배되기에는 적당하지 않다. 강원도 철원군에서 재배하는 파프리카는 여름인 그해 7월에 시중에 유통되지만 파프리카는 이보다 앞선 3-6월 사이에 재배된다. 이로 인해 강원도 철원군에서 파프리카는 주로 하우스를 통한 시설 재배를 하고 있다. 파프리카는 다양한 색깔처럼 효능 또한 색깔에 따라 다르다. 먼저 빨간색은 리코펜과 베타카로틴이 풍부하게 함유되어 있어 노화를 막아준다. 그래서 빨간 파프리카의 경우 생식하면 좋은 것으로 알려져 있다. 다음으로 주황색 파프리카는 눈에 좋은 비타민 A와 B가 함유되어 있다. 여기에 더해 철분과 비타민C가 풍부해서 미백에 효과가 좋다. 주황색 파프리카는 먹지 않고 강판에 간 후 율무가루나 생콩가루를 넣어 일회용 거즈에 얹어서 천연팩으로 사용하여 미백효과를 볼 수 있다. 세 번째로 노란색 파프리카의 경우 혈액의 응고를 방지해주는 역할을 하는데, 이로 인해 심근 경색, 고혈압, 뇌경색의 예방 효과가 있다. 마지막으로 피망으로도 오해받는 초록색 파프리카는 섬유질이 풍부해서 장 건강에 도움을 줄 뿐만 아니라 포만감도 주어 다이어트에 좋다. 이뿐만 아니라 뼈 건강에 좋은 비타민K도 들어 있다. 파프리카는 생식으로 먹거나 소스나 조미료로 만들어 요리에 활용된다.', 'https://ncms.nculture.org/local-specialty/story/'),
('방울토마토', '부여 방울토마토', '충청남도 부여군 세도면', '지역N문화', '충청남도 부여군 세도면 일원은 방울토마토의 주산지이다. 2010년에 부여군 지역농협조합 공동사업법인이 생산을 맡고 있는 부여군의 통합 브랜드인 ''굿뜨래''의 상표를 달고 판매되고 있다. 지하수가 풍부한 넓은 평야지역에 위치한 세도면은 일조량이 많아 이곳에서 생산된 농작물의 당도가 높다. 또한 세도면에는 오랜 충적토양과 사질양토로 이루어져 있어 뿌리식물이 자라기에 최적의 장소이다. 매년 4월 20일부터 6월까지 출하하는 방울토마토는 주문 후 수확이 이루어지는 시스템으로 6브릭스 이상의 상품만을 선별해 수확하므로, 고품질 토마토를 접할 수 있다. 부여군에서는 4대강 공사 이후 토마토 생산이 본격화되었다. 공사로 인해 냇물이 흐르던 곳이 농경지로 변화하면서 금강변에 하나둘 재배시설이 들어섰는데, 그 중에서도 사양토질에서 재배가 용이한 뿌리 식물인 토마토 재배가 활성화 되었다. 토마토는 세계 10대 푸드 중 하나로, 항산화성분인 라이코펜이 함유되어 있고, 당도 적고, 칼로리도 적어 건강식을 원하는 사람들이 즐겨 찾는 음식이다. 부여군에서는 연간 2만 600여 톤을 수확해 전국에서 최대 생산지로 손꼽힌다. 현재 530여 농가가 총 300여 ha의 농경지에서 방울토마토를 재배하고 있어, 전국 방울토마토 재배면적의 5.3%, 총 생산량의 5.6%를 담당하고 있다. 세도면은 금강의 큰 물줄기가 가로 흐르는 지역이다. 금강변의 넓은 충적지는 영양토가 넓게 펼쳐져 있다. 넓은 평지가 펼쳐져 있어 일조량이 좋고, 진흙보다는 모래가 많이 섞인 사질양토로 이루어져 있어 작물 재배에 유리한 조건을 갖추고 있다. 또한 농가의 새바람인 스마트팜이 10여 년 전부터 본격적으로 보급되면서 ICT 기술을 활용한 농작물 재배가 활기를 얻고 있다. 농업인구의 고령화로 인해 일일이 관수(灌水)를 하는 것이 어렵게 되면서 물 뿐만 아니라 영양소 공급에 자동화설비를 추가해 혁신적인 변화를 일으키고 있다. 특히 코코넛 껍질로 만든 인공토양인 코코피트를 공중에 띄워 놓고, 방울토마토를 재배하고 있다. 코코피트에는 농업용수와 배양액이 자동 공급되도록 하는 시스템이 설치되어 있다. 컴퓨터에 수분 공급주기와 양을 입력해 두면 자동적으로 급수된다. 토양에서 재배하는 방식보다 스마트농법을 적용한 농장에서는 수확량도 많지만 무엇보다 좋은 것은 노동력이 많이 절감되었다는 점이다. 관수를 자동으로 하므로 물 걱정을 하지 않게 되었지만 여전히 꽃따기, 수확 등은 사람의 손을 거쳐야 하므로 농가의 일손은 쉴 틈이 없다. 지금은 아니지만 향후 AI 로봇이 과일이 익는 정도를 계산해 수확하는 완전 자동화를 꿈꾸고 있다. 2003년에 부여군의 공동브랜드로 만든 ''굿뜨래''는 좋다(GOOD)와 나무(TREE)의 합성어이다. 금강변의 천혜의 조건 속에서 자라난 최고 품질의 농산물이라는 뜻을 담고 있다. 굿뜨래를 달고 상품화되는 농산물은 모두 12가지 항목의 심사를 거쳐서 브랜드를 승인해 준다. 부여에서 생산되는 방울토마토는 당도가 타 지역보다 조금 높다. 타 지역의 토마토가 7~7.5도의 당도를 지닌데 반해, 부여군에서 생산한 토마토는 7.5~8.5도 정도의 당도를 유지한다. 특히 농약을 사용하지 않고, 지렁이가 살 수 있는 토양을 만들어 땅의 지력을 회복시키는 친환경 농법을 실시하기도 한다. 어렵게 생산한 토마토는 해마다 4월에 방울토마토 축제에서 맛 볼 수 있다. 시세보다 저렴하게 토마토를 구입할 수 있으므로 축제장을 찾는 이들이 많다. 2012년부터 부여에서 생산한 방울토마토는 일본으로 100톤의 물량을 수출하기 시작하였고, 2023년에는 농산물 글로벌화를 통해 홍콩과 몽골 등지로 수출 시장을 확대하였다. 농약잔류검사를 정기적으로 실시하고, 겨울 작기에 적합한 품종을 선택하여 수출길을 열었다. 토마토는 비옥한 토지에서 생산되어 당도와 식감이 우수해 지속적으로 수출물량이 늘고 있다. 토마토에 이어 굿뜨래 수박도 외국인의 입맛을 사로잡고 있다.', 'https://ncms.nculture.org/local-specialty/story/')
ON CONFLICT (crop_name, region) DO NOTHING;
